            *slot, slot_value, extra,
        )?;
        frame.write_slot_with_taint(*slot, slot_value, recovered.taint).map_err(...)?;
    }
    executed = executed.saturating_add(1);
}
```
This restores parity with the accumulator path and removes the dependence on
